// QuerySite queries the site edge of a Source.
func (c *SourceClient) QuerySite(_m *Source) *SiteQuery {
	query := (&SiteClient{config: c.config}).Query()
	query.path = func(context.Context) (fromV *sql.Selector, _ error) {
		id := _m.Id
		step := sqlgraph.NewStep(
			sqlgraph.From(source.Table, source.FieldId, id),
			sqlgraph.To(site.Table, site.FieldId),
			sqlgraph.Edge(sqlgraph.M2O, false, source.SiteTable, source.SiteColumn),
		)
		fromV = sqlgraph.Neighbors(_m.driver.Dialect(), step)
		return fromV, nil
	}
	return query
}

